func TestSentinelErrors(t *testing.T) {
	errs := map[string]error{"ErrUnsupported": ErrUnsupported, "ErrNotIPv4": ErrNotIPv4, "ErrNoRoute": ErrNoRoute}
	for name, err := range errs {
		if err == nil || err.Error() == "" {
